from collections import deque

def bfs(floor, start, goal):
    rows, cols = len(floor), len(floor[0])
    dist = {start: 0}
    q = deque([start])
    while q:
        r, c = q.popleft()
        if (r, c) == goal:
            return dist[(r, c)]
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and floor[nr][nc] == "." and (nr,nc) not in dist:
                dist[(nr,nc)] = dist[(r,c)]+1
                q.append((nr,nc))
    return -1


